function a1(r,c){var s='';while(c>0){var m=(c-1)%26;s=String.fromCharCode(65+m)+s;c=(c-m-1)/26;}return s+r;}
var sh1=ss.getSheetByName('Offering Tape');
var vals1=sh1.getRange('B6:M26').getValues();
for (var r=0;r<vals1.length;r++) log('OT '+(r+6)+': '+JSON.stringify(vals1[r]));
var sh2=ss.getSheetByName('Metric Matrix');
var vals2=sh2.getRange('B6:AB14').getValues();
for (var r=0;r<vals2.length;r++) log('MM '+(r+6)+': '+JSON.stringify(vals2[r]));

var sh=ss.getSheetByName('Metric Matrix');
var dealStartCol=4, dealEndCol=22; // D:V
var cols=[]; for (var c=dealStartCol;c<=dealEndCol;c++) cols.push(c);
function colLetter(n){var s=''; while(n>0){var m=(n-1)%26; s=String.fromCharCode(65+m)+s; n=(n-m-1)/26;} return s;}
function issuerFormula(colLetterTarget, expr){
  var m = "MATCH("+colLetterTarget+"$6,'Offering Tape'!$B$8:$B$26,0)";
  return '=' + expr(m);
}
var formulas=[];
for (var r=8;r<=14;r++) {
  var row=[];
  for (var c=dealStartCol;c<=dealEndCol;c++) {
    var cl=colLetter(c);
    var f='';
    if (r===8) f = issuerFormula(cl, function(m){return "INDEX('Offering Tape'!$E$8:$E$26,"+m+")*INDEX('Offering Tape'!$F$8:$F$26,"+m+")";});
    if (r===9) f = issuerFormula(cl, function(m){return "INDEX('Offering Tape'!$G$8:$G$26,"+m+")*INDEX('Offering Tape'!$H$8:$H$26,"+m+")";});
    if (r===10) f = issuerFormula(cl, function(m){return "INDEX('Offering Tape'!$F$8:$F$26,"+m+")/INDEX('Offering Tape'!$H$8:$H$26,"+m+")-1";});
    if (r===11) f = issuerFormula(cl, function(m){return "INDEX('Offering Tape'!$F$8:$F$26,"+m+")/INDEX('Offering Tape'!$I$8:$I$26,"+m+")-1";});
    if (r===12) f = issuerFormula(cl, function(m){return "INDEX('Offering Tape'!$F$8:$F$26,"+m+")/INDEX('Offering Tape'!$J$8:$J$26,"+m+")-1";});
    if (r===13) f = issuerFormula(cl, function(m){return "INDEX('Offering Tape'!$K$8:$K$26,"+m+")/INDEX('Offering Tape'!$F$8:$F$26,"+m+")-1";});
    if (r===14) f = '=' + cl + '8/' + cl + '9';
    row.push(f);
  }
  formulas.push(row);
}
sh.getRange(8,dealStartCol,7,19).setFormulas(formulas);
var summaryFormulas=[];
for (var r=8;r<=14;r++) {
  summaryFormulas.push([
    '=MAX(D'+r+':V'+r+')',
    '=QUARTILE(D'+r+':V'+r+',3)',
    '=MEDIAN(D'+r+':V'+r+')',
    '=QUARTILE(D'+r+':V'+r+',1)',
    '=MIN(D'+r+':V'+r+')'
  ]);
}
sh.getRange('X8:AB14').setFormulas(summaryFormulas);
sh.getRange('D8:V14').setNumberFormat('0.0');
sh.getRange('X8:AB14').setNumberFormat('0.0');
SpreadsheetApp.flush();
log('Set formulas in D8:V14 and X8:AB14.');
log('D8='+sh.getRange('D8').getValue()+' formula '+sh.getRange('D8').getFormula());
log('D9='+sh.getRange('D9').getValue()+' formula '+sh.getRange('D9').getFormula());
log('D10='+sh.getRange('D10').getValue()+' formula '+sh.getRange('D10').getFormula());
log('V13='+sh.getRange('V13').getValue()+' formula '+sh.getRange('V13').getFormula());
log('X8:AB8 '+JSON.stringify(sh.getRange('X8:AB8').getValues()[0]));
log('Formats D8:V8 sample '+JSON.stringify(sh.getRange('D8:V8').getNumberFormats()[0].slice(0,3))+' ...');
